typedef int UserID;
using AccountID = int;

// Type Aliases (typedef/using) do NOT create new types.

void authenticate(int id) { /* ... */ }

// ERROR: Not an overload! UserID is equivalent to int.
// Compiler treats this as a redeclaration of 'void authenticate(int)'
void authenticate(UserID id) { /* ... */ }

// AccountID is also equivalent to int.
// ERROR: Redeclaration
void authenticate(AccountID id) { /* ... */ }
